import React from 'react';
import { motion } from 'framer-motion';

const posts = [
  {
    id: 1,
    category: 'Cloud Strategy',
    date: 'May 2026',
    title: 'Designing Resilient Cloud Platforms for Growth',
    excerpt:
      'A practical guide to architecting scalable cloud systems that support modern product teams and evolving user demand.',
    image:
      'https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=900&q=80',
  },
  {
    id: 2,
    category: 'Developer Experience',
    date: 'April 2026',
    title: 'Streamlining DevOps with Smart Automation',
    excerpt:
      'How to remove friction from deployment pipelines, improve feedback loops, and empower engineers to ship with confidence.',
    image:
      'https://images.unsplash.com/photo-1517430816045-df4b7de54f10?auto=format&fit=crop&w=900&q=80',
  },
  {
    id: 3,
    category: 'Security & Data',
    date: 'March 2026',
    title: 'Building Secure APIs for Distributed Teams',
    excerpt:
      'Best practices for API design, authentication, and observability when your product must scale across services and regions.',
    image:
      'https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=900&q=80',
  },
];

function BlogSection() {
  return (
    <section className="blog-section" id="blog">
      <div className="section-header">
        <span className="section-label">Latest Articles</span>
        <h2 className="section-title">Fresh thinking for modern engineering teams</h2>
      </div>

      <div className="blog-grid">
        {posts.map((post, index) => (
          <motion.article
            key={post.id}
            className="blog-card"
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.5, delay: index * 0.1 }}
          >
            <div className="blog-card-image">
              <img src={post.image} alt={post.title} />
            </div>
            <div className="blog-card-content">
              <div className="blog-card-meta">
                <span className="blog-category">{post.category}</span>
                <span className="blog-date">{post.date}</span>
              </div>
              <h3>{post.title}</h3>
              <p>{post.excerpt}</p>
              <a href="#contact" className="blog-readmore">
                Read article
              </a>
            </div>
          </motion.article>
        ))}
      </div>
    </section>
  );
}

export default BlogSection;
